func test_postgres_TestPostgres_test_interval_span(self *Case, a Args) Value {
	var time_str, day_time_str Value
	_ = []Value{time_str, day_time_str}
	for _, item_ := range Iter(NewList("1 01:", "1 01:00", "1.5 01:", "-0.25 01:")) {
		time_str = item_
		self.SubTest(func() {
			self.Do(2413, func() { self.ValidateIdentity(F("INTERVAL '", FV{V: time_str}, "'")) })
		}, F("Postgres INTERVAL span, omitted DAY TO MINUTE unit: ", FV{V: time_str}))
	}
	for _, item_ := range Iter(NewList("1 01:01:", "1 01:01:", "1 01:01:01", "1 01:01:01.01", "1.5 01:01:", "-0.25 01:01:")) {
		time_str = item_
		self.SubTest(func() {
			self.Do(2424, func() { self.ValidateIdentity(F("INTERVAL '", FV{V: time_str}, "'")) })
		}, F("Postgres INTERVAL span, omitted DAY TO SECOND unit: ", FV{V: time_str}))
	}
	self.SubTest(func() {
		self.DoAssign(2428, func() { day_time_str = "a > INTERVAL '1 00:00' AND TRUE" }, &day_time_str)
		self.Do(2429, func() { self.ValidateIdentity(day_time_str, "a > INTERVAL '1 00:00' AND TRUE") })
		self.Do(2430, func() { Stmt(M(self, "assertIsInstance", self.ParseOne(day_time_str), A(G("sqlglot.exp"), "And"))) })
	}, "Postgres INTERVAL span, omitted unit with following AND")
	return nil
}

